use std::path::Path;
use std::sync::Arc;

use rustc_errors::emitter::Emitter;
use rustc_errors::registry::Registry;
use rustc_errors::timings::TimingRecord;
use rustc_errors::translation::Translator;
use rustc_errors::{DiagInner, Level, TerminalUrl};
use rustc_lint_defs::Level as LintLevel;
use rustc_span::source_map::SourceMap;
use rustc_span::FileNameDisplayPreference;
use gemini_rustc_data_structures::{SerializableDiagnostic, SerializableSpan, add_diagnostic, clear_diagnostics};

pub struct CollectedEmitter {
    pub diagnostics: Vec<DiagInner>,
    pub translator: Translator, // Store a translator if needed for sub-emitters
    pub sm: Option<Arc<SourceMap>>,
}

impl CollectedEmitter {
    pub fn new(translator: Translator, sm: Option<Arc<SourceMap>>) -> Self {
        gemini_rustc_data_structures::clear_diagnostics(); // Clear diagnostics for a new emitter instance
        CollectedEmitter {
            diagnostics: Vec::new(),
            translator,
            sm,
        }
    }
}

impl Emitter for CollectedEmitter {
    fn emit_diagnostic(&mut self, diag: DiagInner, _registry: &Registry) {
        // Store the DiagInner internally (existing behavior)
        self.diagnostics.push(diag.clone());

        // Convert to SerializableDiagnostic and add to thread-local storage
        let serializable_diag = if let Some(sm) = &self.sm {
            let serializable_span = if let Some(primary_span) = diag.span.primary_span() {
                let span_data = primary_span.data();
                let lo = sm.lookup_char_pos(span_data.lo);
                let hi = sm.lookup_char_pos(span_data.hi);

                Some(SerializableSpan {
                    file_name: sm.span_to_filename(primary_span).display(rustc_span::FileNameDisplayPreference::Local).to_string(), // Convert FileName to String
                    line_start: lo.line,
                    col_start: lo.col.0,
                    line_end: hi.line,
                    col_end: hi.col.0,
                })
            } else {
                None
            };

            SerializableDiagnostic {
                message: diag.messages.get(0).and_then(|(dm, _)| dm.as_str()).map_or("".to_string(), |s| s.to_string()), // Extract String from DiagMessage tuple
                level: diag.level.to_string(),
                span: serializable_span,
            }
        } else {
            SerializableDiagnostic {
                message: diag.messages.get(0).and_then(|(dm, _)| dm.as_str()).map_or("".to_string(), |s| s.to_string()), // Extract String from DiagMessage tuple
                level: diag.level.to_string(),
                span: None,
            }
        };
        add_diagnostic(serializable_diag);
    }

    fn emit_artifact_notification(&mut self, _path: &Path, _artifact_type: &str) {
        // No-op for a collecting emitter
    }

    fn emit_timing_section(&mut self, _record: TimingRecord, _event: rustc_errors::emitter::TimingEvent) {
        // No-op for a collecting emitter
    }

    fn emit_future_breakage_report(&mut self, _diags: Vec<DiagInner>, _registry: &Registry) {
        // No-op for a collecting emitter
    }

    fn emit_unused_externs(&mut self, _lint_level: LintLevel, _unused_externs: &[&str]) {
        // No-op for a collecting emitter
    }

    fn should_show_explain(&self) -> bool {
        false // We are collecting, not displaying explanations
    }

    fn supports_color(&self) -> bool {
        false // No color support needed for collection
    }

    fn source_map(&self) -> Option<&SourceMap> {
        self.sm.as_deref()
    }

    fn translator(&self) -> &Translator {
        &self.translator
    }
}
